// Headless test for the per-civ unit rosters in src/simulation/civ_roster_data.h
// (generated by tools/extract_0ad_rosters.py from 0 A.D.'s templates).
// Also loads ported 0.28 maps (data/maps/*.json) the way session_setup.cpp spawns their units,
// so run it from the repository root. Build and run:
//   g++ -std=c++20 -O2 -Isrc tools/test_civ_roster.cpp src/simulation/simulation.cpp \
//       src/simulation/rms_generator.cpp src/core/job_system.cpp src/network/turn_manager.cpp \
//       src/network/net_host.cpp -lpthread -o /tmp/test_civ_roster && /tmp/test_civ_roster

#define private public
#include "simulation/simulation.h"
#undef private
#include "simulation/rms_generator.h"
#include "simulation/promotion_data.h"

#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <filesystem>
#include <string>
#include <utility>
#include <vector>

using namespace rtso;

// A row no structure trains (after the civ blocks) must be a unit 0 A.D. reaches only by promotion
// (Promotion/Entity of another roster unit, e.g. rome/infantry_antesignanus).
static bool is_promotion_target(const char *id)
{
	for (const PromotionStep &s : PROMOTION_STEPS)
		if (s.target && std::strcmp(s.target, id) == 0) return true;
	return false;
}

// Rows 0.28 retired: they keep their ids for saves but no structure trains them and nothing
// promotes to them (extract_0ad_rosters.py --retire): the Female Citizens 0.28's Civilians
// replace, and the units 0.28 dropped.
static bool is_retired(const char *id)
{
	static const char *const kDropped[] = {"rome/cavalry_auxiliary_b", "cart/cavalry_swordsman_iber_b", "cart/infantry_swordsman_ital_b"};
	if (std::strstr(id, "/support_female_citizen")) return true;
	for (const char *d : kDropped)
		if (std::strcmp(id, d) == 0) return true;
	return false;
}

static int g_checks = 0;
static int g_failed = 0;

static void check(bool ok, const char *name)
{
	++g_checks;
	if (!ok) {
		++g_failed;
		std::printf("FAIL  %s\n", name);
	}
}

// Just enough JSON to read a ported map's "players", "units" and "gaia_units".
struct Json {
	enum Kind { NUL, NUM, STR, ARR, OBJ, BOOL } kind = NUL;
	double num = 0.0;
	std::string str;
	std::vector<Json> arr;
	std::vector<std::pair<std::string, Json>> obj;
	const Json *get(const char *key) const {
		for (const auto &kv : obj)
			if (kv.first == key) return &kv.second;
		return nullptr;
	}
	double number(const char *key, double fallback) const {
		const Json *v = get(key);
		return v && v->kind == NUM ? v->num : fallback;
	}
	std::string string(const char *key) const {
		const Json *v = get(key);
		return v && v->kind == STR ? v->str : std::string();
	}
};

struct JsonReader {
	const char *p;
	void ws() { while (*p == ' ' || *p == '\n' || *p == '\r' || *p == '\t') ++p; }
	std::string text() {
		std::string out;
		for (++p; *p && *p != '"'; ++p) {
			if (*p == '\\' && p[1]) {
				++p;
				if (*p == 'u') { out += '?'; p += 4; continue; } // ids and keys are ASCII
				out += *p == 'n' ? '\n' : *p == 't' ? '\t' : *p;
			} else {
				out += *p;
			}
		}
		if (*p) ++p;
		return out;
	}
	Json value() {
		ws();
		Json v;
		if (*p == '{') {
			v.kind = Json::OBJ;
			++p;
			for (ws(); *p && *p != '}'; ws()) {
				std::string key = text();
				ws();
				++p; // ':'
				v.obj.emplace_back(std::move(key), value());
				ws();
				if (*p == ',') ++p;
			}
			if (*p) ++p;
		} else if (*p == '[') {
			v.kind = Json::ARR;
			++p;
			for (ws(); *p && *p != ']'; ws()) {
				v.arr.push_back(value());
				ws();
				if (*p == ',') ++p;
			}
			if (*p) ++p;
		} else if (*p == '"') {
			v.kind = Json::STR;
			v.str = text();
		} else if (*p == 't' || *p == 'f') {
			v.kind = Json::BOOL;
			v.num = *p == 't';
			p += *p == 't' ? 4 : 5;
		} else if (*p == 'n') {
			p += 4;
		} else {
			v.kind = Json::NUM;
			char *end = nullptr;
			v.num = std::strtod(p, &end);
			p = end && end != p ? end : p + 1;
		}
		return v;
	}
};

static bool read_json(const std::string &path, Json &out)
{
	FILE *f = std::fopen(path.c_str(), "rb");
	if (!f) return false;
	std::string buf;
	char chunk[65536];
	size_t n;
	while ((n = std::fread(chunk, 1, sizeof chunk, f)) > 0) buf.append(chunk, n);
	std::fclose(f);
	JsonReader r{buf.c_str()};
	out = r.value();
	return out.kind == Json::OBJ;
}

static uint16_t row_of(const char *id)
{
	const uint16_t t = civ_unit_template_by_id(id);
	if (t == CIV_UNIT_TEMPLATE_NONE) std::printf("      no roster row %s\n", id);
	return t;
}

// The roster row session_setup.cpp spawns a map's unit as (resolve_map_template, else the
// nearest of its "parents" RTS0 has), or CIV_UNIT_TEMPLATE_NONE when it would fall back to
// its owner's unit of its "type". Skirmish placeholders (skirmish/units/*) are the owner's
// civ unit by design, and units/default_* and units/special_starting_unit (0.28's
// placeholders for the owner's civ unit of a kind) have no template of their own; they count
// as resolved.
static uint16_t map_unit_row(const Json &u)
{
	const std::string t = u.string("template");
	if (t.empty() || t.rfind("skirmish/", 0) == 0 || t.rfind("units/default_", 0) == 0 || t == "units/special_starting_unit")
		return 0;
	int rank = 0;
	uint16_t r = Simulation::resolve_map_template(t.c_str(), &rank);
	if (const Json *parents = u.get("parents"))
		for (size_t k = 0; r == CIV_UNIT_TEMPLATE_NONE && k < parents->arr.size(); ++k)
			r = Simulation::resolve_map_template(parents->arr[k].str.c_str(), &rank);
	return r;
}

// Spawns a ported map's player units as session_setup.cpp does: the map's player N is team
// N - 1 (players 0 and 1 are team 0), with the civ the map gives that player.
static void load_map_units(Simulation &s, const Json &map, std::vector<std::pair<uint32_t, std::string>> &spawned)
{
	s.set_sim_seed(7);
	s.reset();
	if (const Json *players = map.get("players"))
		for (const Json &p : players->arr) {
			const int id = (int)p.number("id", 1);
			const uint8_t team = id <= 1 ? 0 : (uint8_t)(id - 1);
			if (team < MAX_PLAYERS) s.set_team_civ(team, (uint8_t)p.number("civ", CIV_ATHENIANS));
		}
	const Json *units = map.get("units");
	for (size_t i = 0; units && i < units->arr.size(); ++i) {
		const Json &u = units->arr[i];
		const int player = (int)u.number("player", 1);
		uint8_t team = player <= 1 ? 0 : (uint8_t)(player - 1);
		if (team >= MAX_PLAYERS) team = 1;
		const std::string t = u.string("template");
		int rank = 0;
		std::string pick = t;
		if (Simulation::resolve_map_template(t.c_str(), &rank) == CIV_UNIT_TEMPLATE_NONE)
			if (const Json *parents = u.get("parents"))
				for (const Json &pt : parents->arr)
					if (Simulation::resolve_map_template(pt.str.c_str(), &rank) != CIV_UNIT_TEMPLATE_NONE) { pick = pt.str; break; }
		const uint32_t id = s.spawn_map_unit((float)u.number("x", 0.0), (float)u.number("z", 0.0), team, UNIT_SWORDSMAN,
				pick.c_str(), rank);
		spawned.emplace_back(id, t);
	}
}

int main()
{
	char msg[256];

	check(CIV_HAN == 13 && CIV_GAIA == 14 && CIV_GERMANS == 15 && CIV_COUNT == 16,
		"Han after Seleucids, Gaia's saved building civ 14, Germans appended after it");
	check(std::strcmp(civ_info(CIV_HAN).code, "han") == 0, "Han civ code");
	check(std::strcmp(civ_info(CIV_GERMANS).code, "germ") == 0, "Germans civ code");
	// Gaia holds a civ id but no roster: every per-civ table keeps an empty row for it and
	// loops over playable civs skip it.
	{
		int playable = 0;
		bool picks_ok = true;
		for (uint8_t c = 0; c < CIV_COUNT; ++c) playable += is_playable_civ(c);
		for (uint32_t k = 0; k < 2u * PLAYABLE_CIV_COUNT; ++k) picks_ok = picks_ok && is_playable_civ(playable_civ(k));
		check(playable == PLAYABLE_CIV_COUNT && !is_playable_civ(CIV_GAIA) && !is_playable_civ(CIV_COUNT) &&
			!is_playable_civ(-1) && picks_ok && playable_civ(CIV_GAIA) == CIV_GERMANS, "playable civs skip Gaia");
		check(civ_roster_ids(CIV_GAIA).empty() && civ_roster_begin(CIV_GAIA) == civ_roster_end(CIV_GAIA),
			"Gaia has no roster");
	}

	// Rows are grouped by civ and the offsets cover the table exactly.
	check(civ_roster_begin(CIV_ATHENIANS) == 0, "first civ starts at row 0");
	check(civ_roster_end(CIV_COUNT - 1) == CIV_ROSTER_PROMOTION_ONLY_FIRST, "last civ ends where promotion-only rows start");
	for (uint8_t c = 0; c + 1 < CIV_COUNT; ++c)
		check(civ_roster_end(c) == civ_roster_begin(c + 1), "civ blocks are contiguous");
	// After every civ's block: units no structure trains, each a promotion target.
	bool tail_ok = CIV_ROSTER_PROMOTION_ONLY_FIRST < CIV_UNIT_TEMPLATE_COUNT;
	for (uint16_t i = CIV_ROSTER_PROMOTION_ONLY_FIRST; i < CIV_UNIT_TEMPLATE_COUNT; ++i) {
		const CivUnitTemplate &u = civ_unit_template(i);
		if (u.trainers) continue; // a trainable row added later (civ_roster_ids)
		if (u.flags & ROSTER_RELIC) continue; // a catafalque: Capture the Relic places it
		if (u.flags & ROSTER_MAP_ONLY) continue; // only maps place it: checked below
		bool upgrade_target = false; // reached by a unit Upgrade (the Immortals' bow)
		for (const CivUnitUpgrade *up = civ_unit_upgrade_table(); up->from != 0xFFFF; ++up)
			upgrade_target = upgrade_target || up->to == i;
		if (upgrade_target || is_retired(u.id)) continue;
		if (!is_promotion_target(u.id) || u.civ >= CIV_COUNT || u.hp <= 0.0f) {
			tail_ok = false;
			std::printf("      bad promotion-only row %u %s\n", i, u.id);
		}
	}
	check(tail_ok, "promotion-only and upgrade-only rows (Antesignani, Olympic champion, Immortal archer, ...) follow the civ blocks");
	for (uint8_t c = 0; c < CIV_COUNT; ++c) {
		if (!is_playable_civ(c)) continue; // Gaia: checked above
		// The civ's block plus the rows appended after the promotion-only ones (the Germans'
		// whole roster, everyone's Civilians).
		const std::vector<uint16_t> &ids = civ_roster_ids(c);
		int heroes = 0;
		bool rows_ok = true;
		for (uint16_t i : ids) {
			const CivUnitTemplate &u = civ_unit_template(i);
			// A row 0.28 no longer trains: retired, or reached only by promotion (Marian Legionaries).
			const bool retired = is_retired(u.id);
			if (u.civ != c || u.unit_type >= UNIT_TYPE_COUNT || u.hp <= 0.0f || u.speed <= 0.0f ||
					u.phase < 1 || u.phase > 3 || (!u.trainers && !retired && !is_promotion_target(u.id)) ||
					(u.trainers && retired) || u.train_time <= 0.0f) {
				rows_ok = false;
				std::printf("      bad row %u %s\n", i, u.id);
			}
			if (u.attack_damage > 0.0f && (u.attack_range <= 0.0f || u.attack_cooldown <= 0.0f)) {
				rows_ok = false;
				std::printf("      bad attack %u %s\n", i, u.id);
			}
			// Fire (fire ships) has no roster column: it lives in civ_attack_data.h.
			float split = u.hack_damage + u.pierce_damage + u.crush_damage + unit_combat(i, u.unit_type).fire;
			if (split < u.attack_damage - 0.01f || split > u.attack_damage + 0.01f) {
				rows_ok = false;
				std::printf("      bad damage split %u %s\n", i, u.id);
			}
			for (int16_t a : u.auras)
				if (a < -1 || a >= (int16_t)CIV_HERO_AURA_COUNT) rows_ok = false;
			if (u.flags & ROSTER_HERO) {
				++heroes;
				if (u.unit_type != UNIT_HERO || u.auras[0] < 0) rows_ok = false;
			}
		}
		std::snprintf(msg, sizeof msg, "%s rows valid", civ_info(c).name);
		check(rows_ok, msg);
		std::snprintf(msg, sizeof msg, "%s has its own roster (%d units)", civ_info(c).name, (int)ids.size());
		check(ids.size() >= 15, msg);
		std::snprintf(msg, sizeof msg, "%s has at least 3 heroes (%d)", civ_info(c).name, heroes);
		check(heroes >= 3, msg);

		// Every civ keeps the basics an RTS0 match needs.
		static const UnitType kCore[] = {UNIT_VILLAGER, UNIT_FEMALE_CITIZEN, UNIT_SPEARMAN, UNIT_CAVALRY,
			UNIT_FISHING_BOAT, UNIT_TRIREME, UNIT_TRADER, UNIT_HEALER, UNIT_SIEGE_RAM, UNIT_HERO};
		for (UnitType t : kCore) {
			std::snprintf(msg, sizeof msg, "%s can train %s", civ_info(c).name, unit_type_name(t));
			check(civ_can_train(c, t), msg);
			uint16_t d = civ_default_template(c, t);
			std::snprintf(msg, sizeof msg, "%s default %s matches class", civ_info(c).name, unit_type_name(t));
			check(d != CIV_UNIT_TEMPLATE_NONE && civ_unit_template(d).unit_type == t &&
				civ_unit_template(d).civ == c, msg);
		}
		uint16_t sp = civ_default_template(c, UNIT_SPEARMAN);
		std::snprintf(msg, sizeof msg, "%s default spearman is a citizen soldier", civ_info(c).name);
		check(!(civ_unit_template(sp).flags & (ROSTER_HERO | ROSTER_CHAMPION)), msg);
	}

	// Rosters differ: civs field their own named units with their own stats.
	const CivUnitTemplate &hoplite = civ_unit_template(civ_default_template(CIV_ATHENIANS, UNIT_SPEARMAN));
	check(std::strcmp(hoplite.name, "Athenian Hoplite") == 0, "Athenian spearman is the Athenian Hoplite");
	const CivUnitTemplate &han_archer = civ_unit_template(civ_default_template(CIV_HAN, UNIT_ARCHER));
	check(std::strstr(han_archer.id, "han/") == han_archer.id, "Han archer comes from the Han roster");
	check(civ_can_train(CIV_GAULS, UNIT_CARNYX), "Gauls train the carnyx trumpeter");
	check(civ_can_train(CIV_MAURYANS, UNIT_WORKER_ELEPHANT), "Mauryans train worker elephants");
	check(civ_can_train(CIV_BRITONS, UNIT_WAR_DOG), "Britons train war dogs");
	check(!civ_can_train(CIV_ATHENIANS, UNIT_ELEPHANT), "Athenians have no elephants");
	check(!civ_can_train(CIV_HAN, UNIT_ELEPHANT), "Han have no elephants");

	bool found_pericles = false;
	for (uint16_t i = civ_roster_begin(CIV_ATHENIANS); i < civ_roster_end(CIV_ATHENIANS); ++i) {
		const CivUnitTemplate &u = civ_unit_template(i);
		if (std::strcmp(u.name, "Pericles") == 0) {
			found_pericles = (u.flags & ROSTER_HERO) && u.auras[0] >= 0 &&
				std::strstr(civ_hero_aura(u.auras[0]).id, "athen_hero_pericles") != nullptr;
		}
	}
	check(found_pericles, "Pericles is an Athenian hero with his own aura");

	// Civ bonus building masks cover every BuildingType, including ids above 15.
	check(bld_bit(BLD_EMBASSY).test(BLD_EMBASSY) && bld_bit(BLD_TYPE_COUNT - 1).test(BLD_TYPE_COUNT - 1) && bld_bit(127).test(127), "bld_bit covers every building id");
	check(civ_bonus_mult(CIV_ATHENIANS, CIV_BONUS_BUILDING_HP, BLD_EMBASSY) > 1.05f,
		"Hellenic Architecture reaches buildings above id 15");
	check(civ_bonus_mult(CIV_SELEUCIDS, CIV_BONUS_BUILDING_BUILD_TIME, BLD_FIELD) < 0.5f,
		"Seleucid farms build faster");
	check(civ_bonus_mult(CIV_SELEUCIDS, CIV_BONUS_BUILDING_BUILD_TIME, BLD_HOUSE) == 1.0f,
		"Seleucid farm bonus stays on fields");

	// Siege towers: trained by name only, never the bolt-shooter default.
	const uint8_t tower_civs[] = {CIV_MACEDONIANS, CIV_KUSHITES, CIV_PTOLEMIES, CIV_SELEUCIDS, CIV_HAN};
	for (uint8_t c : tower_civs) {
		bool tower = false;
		for (uint16_t i = civ_roster_begin(c); i < civ_roster_end(c); ++i) {
			const CivUnitTemplate &u = civ_unit_template(i);
			if (u.flags & ROSTER_SIEGE_TOWER)
				tower = u.unit_type == UNIT_BOLT_SHOOTER && (u.flags & ROSTER_RANGED) && u.hp >= 400.0f &&
					!(u.flags & ROSTER_PACKABLE) && (u.trainers & bld_bit(BLD_ARSENAL));
		}
		std::snprintf(msg, sizeof(msg), "%s trains a siege tower", civ_info(c).code);
		check(tower, msg);
		uint16_t d = civ_default_template(c, UNIT_BOLT_SHOOTER);
		std::snprintf(msg, sizeof(msg), "%s default bolt shooter is not a siege tower", civ_info(c).code);
		check(d == CIV_UNIT_TEMPLATE_NONE || !(civ_unit_template(d).flags & ROSTER_SIEGE_TOWER), msg);
	}
	check(!civ_can_train(CIV_KUSHITES, UNIT_BOLT_SHOOTER) ||
		civ_default_template(CIV_KUSHITES, UNIT_BOLT_SHOOTER) != CIV_UNIT_TEMPLATE_NONE,
		"Kush bolt-shooter class only when a real bolt shooter exists");
	// 0 A.D. Pack: stone throwers and bolt shooters pack, rams do not.
	for (uint8_t c = 0; c < CIV_COUNT; ++c) {
		for (uint16_t i = civ_roster_begin(c); i < civ_roster_end(c); ++i) {
			const CivUnitTemplate &u = civ_unit_template(i);
			if (u.unit_type == UNIT_SIEGE_RAM && (u.flags & ROSTER_PACKABLE)) check(false, u.id);
			if (std::strstr(u.id, "_packed") && !(u.flags & ROSTER_PACKABLE)) check(false, u.id);
		}
	}
	check(civ_default_template(CIV_ROMANS, UNIT_CATAPULT) != CIV_UNIT_TEMPLATE_NONE &&
		(civ_unit_template(civ_default_template(CIV_ROMANS, UNIT_CATAPULT)).flags & ROSTER_PACKABLE),
		"Roman catapult packs");

	// Champion unlocks come from each template's 0 A.D. Identity/Requirements;
	// other rows are only gated by civ-only techs (Neodamodes, Marian Reforms, ...).
	int gated = 0;
	for (uint16_t i = 0; i < CIV_UNIT_TEMPLATE_COUNT; ++i) {
		const CivUnitTemplate &u = civ_unit_template(i);
		if (u.unlock_tech == TECH_NONE) continue;
		++gated;
		if (!(u.flags & ROSTER_CHAMPION) && tech_info(u.unlock_tech).civ_mask == (uint16_t)(((1u << CIV_COUNT) - 1) & ~(1u << CIV_GAIA)))
			check(false, u.id);
	}
	check(gated >= 20, "champion rows carry their unlock technology");
	bool neodamodes = false, champion_hoplite = false;
	for (uint16_t i = civ_roster_begin(CIV_SPARTANS); i < civ_roster_end(CIV_SPARTANS); ++i) {
		const CivUnitTemplate &u = civ_unit_template(i);
		if (std::strcmp(u.id, "spart/infantry_spearman_neodamodes") == 0)
			neodamodes = u.unlock_tech == TECH_UNLOCK_NEODAMODES;
		if (std::strcmp(u.id, "spart/champion_infantry_spear") == 0)
			champion_hoplite = (u.tech_classes & (TC_CHAMPION | TC_INFANTRY | TC_SPEARMAN))
				== (TC_CHAMPION | TC_INFANTRY | TC_SPEARMAN) && !(u.tech_classes & TC_CITIZENSOLDIER);
	}
	check(neodamodes, "Neodamodes wait for Unlock Neodamodes at the Gerousia");
	check(champion_hoplite, "Spartan champion hoplites carry 0 A.D.'s Champion Infantry Spearman classes");
	for (uint16_t i = civ_roster_begin(CIV_ROMANS); i < civ_roster_end(CIV_ROMANS); ++i)
		if (std::strcmp(civ_unit_template(i).id, "rome/champion_infantry_swordsman") == 0)
			check(civ_unit_template(i).unlock_tech == TECH_UNLOCK_CHAMPION_INFANTRY,
				"Roman champion infantry waits for Unlock Champion Infantry");

	// A unit's own auras outside the civ's hero set: the centurion's Combat Leadership
	// and Century Maneuvers (units/centurion_1, units/centurion_2).
	for (uint16_t i = civ_roster_begin(CIV_ROMANS); i < civ_roster_end(CIV_ROMANS); ++i) {
		const CivUnitTemplate &u = civ_unit_template(i);
		if (std::strcmp(u.id, "rome/champion_infantry_swordsman_centurion") != 0) continue;
		check(u.auras[0] >= 0 && std::strcmp(civ_hero_aura(u.auras[0]).id, "centurion_1") == 0 &&
			u.auras[1] >= 0 && std::strcmp(civ_hero_aura(u.auras[1]).id, "centurion_2") == 0,
			"the Roman centurion carries Combat Leadership and Century Maneuvers");
	}

	// Templates only 0.28's maps and Survival's Gaia waves place (extract_0ad_rosters.py MAP_ROWS)
	// have rows of their own, appended after the 463 rows saves already store, which keep their ids.
	{
		uint64_t h = 0xcbf29ce484222325ull; // FNV-1a over rows 0-462's ids, each with a newline
		for (uint16_t i = 0; i < 463 && i < CIV_UNIT_TEMPLATE_COUNT; ++i)
			for (const char *c = civ_unit_template(i).id;; ++c) {
				h = (h ^ (uint8_t)(*c ? *c : '\n')) * 0x100000001b3ull;
				if (!*c) break;
			}
		check(CIV_UNIT_TEMPLATE_COUNT >= 502 && h == 0x8529c3cbea01b915ull, "rows 0-462 keep their template ids");
		check(std::strcmp(civ_unit_template(0).id, "athen/cavalry_javelineer_b") == 0 &&
			std::strcmp(civ_unit_template(462).id, "han/support_healer_e") == 0, "first and last pre-map rows in place");
		check(CIV_UNIT_TEMPLATE_COUNT <= 64 * CIV_TEMPLATE_WORDS, "roster fits its template bitsets");
		bool map_rows_ok = true;
		int map_rows = 0;
		for (uint16_t i = 0; i < CIV_UNIT_TEMPLATE_COUNT; ++i) {
			const CivUnitTemplate &u = civ_unit_template(i);
			if (!(u.flags & ROSTER_MAP_ONLY)) continue;
			++map_rows;
			if (i < 463 || u.trainers || u.civ >= CIV_COUNT || u.hp <= 0.0f || u.speed <= 0.0f || u.unit_type >= UNIT_TYPE_COUNT) {
				map_rows_ok = false;
				std::printf("      bad map-only row %u %s\n", i, u.id);
			}
			// A units/<civ>/ template keeps its civ's slot; one with no civ is Gaia's.
			const char *slash = std::strchr(u.id, '/');
			const bool civ_path = slash && std::strchr(slash + 1, '/') == nullptr && std::strncmp(u.id, "pirates/", 8) != 0;
			if (civ_path ? (u.civ == CIV_GAIA || std::strncmp(civ_info(u.civ).code, u.id, (size_t)(slash - u.id)) != 0) : u.civ != CIV_GAIA) {
				map_rows_ok = false;
				std::printf("      map-only row %s in civ slot %u\n", u.id, u.civ);
			}
		}
		std::snprintf(msg, sizeof msg, "map-only rows (%d) are trained nowhere and sit in their civ's slot", map_rows);
		check(map_rows_ok && map_rows == 53, msg); // 44 + the Marian legionaries _02-_05 + Xenophon, Leonidas 300, the Arstibara, Shoushe and plane
		for (uint8_t c = 0; c < CIV_COUNT; ++c)
			for (uint16_t i : civ_roster_ids(c))
				if (civ_unit_template(i).flags & ROSTER_MAP_ONLY) check(false, "a map-only row is in a civ's trainable roster");

		// 0.28's own stats. samnite_swordsman: template_unit_champion_infantry_swordsman (Health 200,
		// Hack 16, RepeatTime 750) with mixins/mercenary.xml (attack x1.1) and merc_inf (60 metal).
		const uint16_t sw = row_of("samnite_swordsman");
		if (sw != CIV_UNIT_TEMPLATE_NONE) {
			const CivUnitTemplate &u = civ_unit_template(sw);
			check(u.civ == CIV_GAIA && u.unit_type == UNIT_SWORDSMAN && u.hp == 200.0f &&
				std::fabs(u.hack_damage - 17.6f) < 0.01f && std::fabs(u.attack_damage - 17.6f) < 0.01f &&
				std::fabs(u.attack_cooldown - 0.75f) < 0.001f && u.gold_cost == 60 &&
				(u.flags & (ROSTER_CHAMPION | ROSTER_MERCENARY)) == (ROSTER_CHAMPION | ROSTER_MERCENARY),
				"Samnite Swordsman: 200 health, 17.6 hack every 0.75 s, 60 metal, a mercenary champion");
		}
		// pirates/ship_arrow: template_unit_ship_warship_arrow (Health 1000, Pierce 32) with
		// mixins/pirate.xml (Health x1.2, +200 metal, no population).
		const uint16_t pa = row_of("pirates/ship_arrow");
		if (pa != CIV_UNIT_TEMPLATE_NONE) {
			const CivUnitTemplate &u = civ_unit_template(pa);
			check(u.civ == CIV_GAIA && u.unit_type == UNIT_TRIREME && u.hp == 1200.0f && u.pierce_damage == 32.0f &&
				u.attack_damage == 32.0f && (u.flags & ROSTER_RANGED) && u.gold_cost == 300 && u.pop_cost == 0 &&
				std::strcmp(u.specific_name, "Rhodian Marauder") == 0,
				"Rhodian Marauder: 1200 health, 32 pierce arrows, no population");
		}
		// mace/hero_craterus: template_unit_hero_infantry_swordsman (Health 1000, Hack 26,
		// RepeatTime 750) and his own aura.
		const uint16_t cr = row_of("mace/hero_craterus");
		if (cr != CIV_UNIT_TEMPLATE_NONE) {
			const CivUnitTemplate &u = civ_unit_template(cr);
			check(u.civ == CIV_MACEDONIANS && u.unit_type == UNIT_HERO && (u.flags & ROSTER_HERO) && u.hp == 1000.0f &&
				u.hack_damage == 26.0f && u.attack_damage == 26.0f && std::fabs(u.attack_cooldown - 0.75f) < 0.001f &&
				u.auras[0] >= 0 && std::strcmp(civ_hero_aura(u.auras[0]).id, "mace_hero_craterus") == 0,
				"Craterus: 1000 health, 26 hack every 0.75 s, his own aura");
		}
		// Regicide.js draws each player's hero from every Hero template of its civ
		// (GetTemplateNamesByClasses), Xenophon and the 300's Leonidas included.
		{
			static const struct { uint8_t civ; int heroes; } kPools[] = {
				{CIV_ATHENIANS, 5}, {CIV_SPARTANS, 4}, {CIV_PERSIANS, 4}, {CIV_ROMANS, 6}, {CIV_CARTHAGINIANS, 3},
				{CIV_MACEDONIANS, 6}, {CIV_BRITONS, 6}, {CIV_GAULS, 4}, {CIV_IBERIANS, 4}, {CIV_MAURYANS, 6},
				{CIV_KUSHITES, 5}, {CIV_PTOLEMIES, 3}, {CIV_SELEUCIDS, 3}, {CIV_HAN, 7}, {CIV_GERMANS, 3}};
			bool pools = row_of("athen/hero_xenophon") != CIV_UNIT_TEMPLATE_NONE &&
					row_of("spart/hero_leonidas_300") != CIV_UNIT_TEMPLATE_NONE;
			for (const auto &p : kPools) {
				int n = 0;
				for (uint16_t i = 0; i < CIV_UNIT_TEMPLATE_COUNT; ++i) {
					const CivUnitTemplate &u = civ_unit_template(i);
					if (u.civ == p.civ && (u.flags & ROSTER_HERO) && !std::strstr(u.id, "/rts0_")) ++n;
				}
				if (n != p.heroes) {
					std::printf("  civ %d: %d heroes, 0.28 has %d\n", p.civ, n, p.heroes);
					pools = false;
				}
			}
			check(pools, "each civ's Regicide hero pool holds all of 0.28's Hero templates");
		}
		static const char *const kMapRows[] = {"samnite_spearman", "samnite_skirmisher", "athen/infantry_marine_archer_b",
			"pers/kardakes_hoplite", "pers/kardakes_skirmisher", "cart/champion_pikeman", "spart/champion_infantry_pike",
			"rome/infantry_swordsman_slave", "pers/hero_xerxes_i_chariot", "ptol/champion_juggernaut",
			"mace/hero_philip_ii_pike", "mace/hero_pyrrhus_i", "kush/hero_amanirenas_infantry", "kush/hero_harsiotef",
			"maur/hero_ashoka_infantry", "maur/hero_chandragupta_infantry", "maur/hero_bindusara_infantry",
			"han/hero_han_xin", "han/hero_liu_bang", "han/hero_wei_qing", "han/hero_wei_qing_horse",
			"brit/hero_boudicca_sword", "brit/hero_boudicca_cavalry_javelineer", "brit/hero_cunobelin_infantry",
			"rome/hero_marcellus_infantry", "rome/hero_maximus_infantry", "rome/hero_scipio_infantry",
			"gaul/hero_vercingetorix_infantry", "iber/hero_indibil_infantry", "han/champion_infantry_archer_academy",
			"han/cavalry_crossbowman_b", "pirates/ship_merchant", "pirates/ship_scout", "noldor_warship",
			"viking_longship", "merc_black_cloak", "pers/arstibara", "han/siege_shoushe", "plane"};
		bool all_rows = true;
		for (const char *id : kMapRows) all_rows = row_of(id) != CIV_UNIT_TEMPLATE_NONE && all_rows;
		check(all_rows, "every map-only 0.28 template has its own row");
		int rank = 0;
		check(Simulation::resolve_map_template("athen/infantry_marine_archer_e", &rank) == row_of("athen/infantry_marine_archer_b") &&
			rank == 3, "the Cretan archer's _e template is its _b row at Elite");
		rank = 0;
		check(Simulation::resolve_map_template("han/cavalry_crossbowman_a", &rank) == row_of("han/cavalry_crossbowman_b") &&
			rank == 2, "the Han cavalry crossbowman's _a template is its _b row at Advanced");
	}

	// Ported maps spawn their units as their own templates: the Roman player's Samnite
	// mercenaries in Battle for the Tiber and Death Canyon - Invasion Force, as in 0.28.
	{
		static Simulation sim;
		for (const char *name : {"battle_for_the_tiber", "death_canyon_invasion_force"}) {
			Json map;
			const std::string path = std::string("data/maps/") + name + ".json";
			if (!read_json(path, map)) {
				check(false, "map file readable (run from the repository root)");
				continue;
			}
			std::vector<std::pair<uint32_t, std::string>> spawned;
			load_map_units(sim, map, spawned);
			int samnites = 0, own = 0;
			for (const auto &[id, tmpl] : spawned) {
				if (tmpl.rfind("samnite_", 0) != 0) continue;
				++samnites;
				const int32_t i = sim.lookup_unit(id);
				if (i < 0) continue;
				const uint16_t row = civ_unit_template_by_id(tmpl.c_str());
				const CivUnitTemplate &u = civ_unit_template(row);
				// 0.28 mercenaries start Advanced (RequiredXp 0 at Basic): health x1.25.
				if (row != CIV_UNIT_TEMPLATE_NONE && sim.units_.tmpl[i] == row && sim.units_.unit_type[i] == u.unit_type &&
						sim.units_.team[i] == 1 && sim.team_civ(1) == CIV_ROMANS && sim.units_.max_hp[i] >= u.hp)
					++own;
			}
			std::snprintf(msg, sizeof msg, "%s: the Roman player's %d Samnites spawn as their own templates (%d)", name, samnites, own);
			check(samnites > 0 && own == samnites, msg);
		}

		// A hero form, a pirate ship and a promoted Cretan archer, as maps place them.
		sim.set_sim_seed(7);
		sim.reset();
		sim.set_team_civ(0, CIV_MACEDONIANS);
		sim.set_team_civ(1, CIV_ROMANS);
		// A map's _unpacked siege stands in as its packed row, unpacked (REMAINING_GAPS SU2).
		{
			const int32_t up = sim.lookup_unit(sim.spawn_map_unit(-20.0f, 0.0f, 0, UNIT_SWORDSMAN, "athen/siege_lithobolos_packed", 0, true));
			const int32_t pk = sim.lookup_unit(sim.spawn_map_unit(-30.0f, 0.0f, 0, UNIT_SWORDSMAN, "athen/siege_lithobolos_packed"));
			check(up >= 0 && pk >= 0 && sim.units_.pack_state[up] == PACK_UNPACKED && sim.units_.pack_state[pk] == PACK_PACKED,
				"a map's unpacked stone thrower starts unpacked, a packed one packed");
		}
		int32_t i = sim.lookup_unit(sim.spawn_map_unit(0.0f, 0.0f, 0, UNIT_HERO, "mace/hero_craterus"));
		check(i >= 0 && sim.units_.tmpl[i] == civ_unit_template_by_id("mace/hero_craterus") && sim.units_.max_hp[i] == 1000.0f,
			"a map's Craterus spawns as Craterus, not the Macedonian default hero");
		i = sim.lookup_unit(sim.spawn_map_unit(10.0f, 0.0f, 1, UNIT_HERO, "rome/hero_scipio_infantry"));
		check(i >= 0 && sim.units_.tmpl[i] == civ_unit_template_by_id("rome/hero_scipio_infantry"),
			"Scipio's infantry form spawns as itself");
		i = sim.lookup_unit(sim.spawn_gaia_unit(20.0f, 20.0f, UNIT_TRIREME, "pirates/ship_arrow"));
		check(i >= 0 && sim.units_.tmpl[i] == civ_unit_template_by_id("pirates/ship_arrow") && sim.units_.team[i] == GAIA_PLAYER &&
			sim.units_.max_hp[i] == 1200.0f, "a Gaia pirate ship spawns as the Rhodian Marauder");
		i = sim.lookup_unit(sim.spawn_map_unit(30.0f, 0.0f, 1, UNIT_TRIREME, "pirates/ship_scout"));
		check(i >= 0 && sim.units_.tmpl[i] == civ_unit_template_by_id("pirates/ship_scout") && sim.units_.team[i] == 1,
			"a player's pirate ship keeps its template whatever the owner's civ");
		i = sim.lookup_unit(sim.spawn_map_unit(-10.0f, 0.0f, 0, UNIT_ARCHER, "athen/infantry_marine_archer_e"));
		check(i >= 0 && sim.units_.tmpl[i] == civ_unit_template_by_id("athen/infantry_marine_archer_b") && sim.units_.rank[i] == 3,
			"a map's elite Cretan archer spawns as the Cretan archer at Elite");
	}

	// Survival of the Fittest's fire-raiser (units/theb_siege_fireraiser, row 506, after the rows
	// saves already store): template_unit_siege_flamethrower's Ranged "Fire" attack, 100 Fire from
	// 10 to 15 m (x COMBAT_DISTANCE_SCALE), and its DeathDamage, 600 Fire over 20 m (x
	// AREA_DAMAGE_SCALE) with FriendlyFire: dying, it burns every owner's units, Gaia's included.
	// No 0.28 template resists Fire. The fire ship's DeathDamage stays Crush 500 over 22 m.
	{
		const uint16_t fr = civ_unit_template_by_id("theb_siege_fireraiser");
		check(fr == 506, "the fire-raiser is row 506, after every older row");
		const CivUnitTemplate &u = civ_unit_template(fr < CIV_UNIT_TEMPLATE_COUNT ? fr : 0);
		check(fr < CIV_UNIT_TEMPLATE_COUNT && u.civ == CIV_GAIA && u.unit_type == UNIT_BOLT_SHOOTER &&
			(u.flags & ROSTER_MAP_ONLY) && !u.trainers && u.hp == 300.0f && u.wood_cost == 300 && u.gold_cost == 150 &&
			(u.tech_classes & TC_SIEGE), "the fire-raiser is a Gaia map-only bolt-shooter-class siege engine, 300 hp");
		const CombatProfile &cp = combat_template_table()[fr < CIV_UNIT_TEMPLATE_COUNT ? fr : 0];
		check(u.attack_damage == 100.0f && u.hack_damage == 0.0f && u.pierce_damage == 0.0f && u.crush_damage == 0.0f && cp.fire == 100.0f &&
			u.attack_cooldown == 2.0f && cp.prepare == 2.0f && cp.proj_speed == 10.0f && cp.spread == 2.0f,
			"its attack is 100 Fire every 2 s, a projectile at 10 m/s");
		check(std::fabs(u.attack_range - 15.0f * COMBAT_DISTANCE_SCALE) < 1e-4f &&
			std::fabs(u.attack_range * unit_min_range_ratio(UNIT_BOLT_SHOOTER, fr) - 10.0f * COMBAT_DISTANCE_SCALE) < 1e-4f,
			"it fires from 10 to 15 m, scaled as ranged ranges are");

		static Simulation sim;
		sim.set_sim_seed(7);
		sim.reset();
		sim.set_map_half(64.0f);
		sim.set_terrain_data(std::vector<float>(65 * 65, 2.0f), 65, 0.0f);
		for (uint8_t p = 0; p < 2; ++p) sim.set_player_active(p, true, false);
		sim.set_team_civ(0, CIV_ATHENIANS);
		sim.set_team_civ(1, CIV_ROMANS);
		sim.set_victory_condition(VICTORY_ENDLESS);
		const uint32_t fire = sim.spawn_gaia_unit(0.0f, 0.0f, UNIT_BOLT_SHOOTER, "theb_siege_fireraiser");
		int32_t i = sim.lookup_unit(fire);
		check(i >= 0 && sim.units_.tmpl[i] == fr && sim.units_.team[i] == GAIA_PLAYER && sim.units_.unit_type[i] == UNIT_BOLT_SHOOTER &&
			sim.units_.max_hp[i] == 300.0f, "spawn_gaia_unit fields the fire-raiser as Gaia");
		if (i >= 0) {
			float dmg[4];
			sim.unit_tech_damage((size_t)i, dmg);
			const Simulation::UnitDetails d = sim.unit_details((size_t)i);
			std::printf("      fire-raiser: hack %.0f pierce %.0f crush %.0f fire %.0f, range %.1f-%.1f m\n",
				dmg[0], dmg[1], dmg[2], dmg[3], d.min_range, d.max_range);
			check(dmg[0] == 0.0f && dmg[1] == 0.0f && dmg[2] == 0.0f && dmg[3] == 100.0f && d.ranged &&
				std::fabs(d.min_range - 10.0f) < 1e-3f && std::fabs(d.max_range - 15.0f) < 1e-3f,
				"the Gaia fire-raiser's attack deals 100 Fire from 10 to 15 m");
		}
		const DeathDamageInfo *dd = Simulation::death_damage_info(Simulation::unit_death_damage_row(fr));
		check(dd && dd->fire && dd->friendly_fire && dd->damage == 600.0f && dd->ship_building_mult == 1.0f &&
			std::fabs(dd->range - 20.0f * AREA_DAMAGE_SCALE) < 1e-4f, "its DeathDamage is 600 Fire over 20 m, friendly fire on");
		const uint16_t lit = civ_unit_template_by_id("brit/ship_fire_fire");
		const DeathDamageInfo *ship = Simulation::death_damage_info(Simulation::unit_death_damage_row(lit));
		check(Simulation::unit_death_damage_row(lit) == 1 && ship && !ship->fire && !ship->friendly_fire && ship->damage == 500.0f &&
			ship->ship_building_mult == 3.0f && std::fabs(ship->range - 22.0f * AREA_DAMAGE_SCALE) < 1e-4f &&
			Simulation::unit_death_damage_row(civ_unit_template_by_id("brit/ship_fire")) == 0 &&
			Simulation::unit_death_damage_row(civ_unit_template_by_id("athen/siege_oxybeles_packed")) == 0,
			"the ignited fire ship's DeathDamage is unchanged (row 1 as older saves store it: Crush 500 over 22 m, x3, enemies only)");

		// Its blast: a Gaia Samnite, two players' units and a ram beside it, one unit out of reach.
		const uint32_t gaia = sim.spawn_gaia_unit(2.0f, 0.0f, UNIT_SPEARMAN, "samnite_spearman");
		const uint32_t own0 = sim.spawn_unit(0.0f, 3.0f, 0, UNIT_SPEARMAN);
		const uint32_t foe1 = sim.spawn_unit(-3.0f, 0.0f, 1, UNIT_SWORDSMAN);
		const uint32_t ram = sim.spawn_unit(0.0f, -10.0f, 1, UNIT_SIEGE_RAM);
		const uint32_t far0 = sim.spawn_unit(16.0f, 0.0f, 0, UNIT_SPEARMAN);
		uint32_t all[5] = {gaia, own0, foe1, ram, far0};
		sim.order_set_stance(all, 5, STANCE_PASSIVE);
		auto hp = [&](uint32_t id) { const int32_t k = sim.lookup_unit(id); return k >= 0 && sim.units_.alive[k] ? sim.units_.hp[k] : 0.0f; };
		const int32_t ri = sim.lookup_unit(ram);
		const float ram0 = hp(ram), far_hp = hp(far0);
		const float rd = 10.0f - unit_collision_radius(UNIT_SIEGE_RAM), r = 20.0f * AREA_DAMAGE_SCALE;
		const float expect = 600.0f * (1.0f - rd * rd / (r * r)); // Fire: no resistance applies
		float res[3] = {0, 0, 0};
		if (ri >= 0) sim.unit_resistance((size_t)ri, res);
		sim.cmd_delete(GAIA_PLAYER, &fire, 1);
		for (int t = 0; t < 10; ++t) sim.tick(Simulation::FIXED_STEP);
		std::printf("      fire-raiser blast: Gaia %.0f, player 0 %.0f, player 1 %.0f, ram %.0f -> %.0f (expected -%.0f, crush armour %.0f), far %.0f -> %.0f\n",
			hp(gaia), hp(own0), hp(foe1), ram0, hp(ram), expect, res[2], far_hp, hp(far0));
		check(hp(gaia) == 0.0f && hp(own0) == 0.0f && hp(foe1) == 0.0f,
			"the fire-raiser's death burns every owner's units within 20 m, Gaia's own included");
		check(ram0 > 0.0f && res[2] > 0.0f && std::fabs((ram0 - hp(ram)) - expect) < 0.5f,
			"its 600 Fire falls off over 20 m and ignores crush resistance");
		check(far_hp > 0.0f && hp(far0) == far_hp, "a unit 16 m away is out of its 20 m (x0.6) blast");
	}

	// No ported map's unit falls back to its owner's generic unit any more.
	{
		int maps = 0, missing = 0, left_out = 0;
		std::error_code ec;
		for (const auto &e : std::filesystem::recursive_directory_iterator("data/maps", ec)) {
			if (e.path().extension() != ".json") continue;
			Json map;
			if (!read_json(e.path().string(), map)) continue;
			++maps;
			for (const char *key : {"units", "gaia_units"})
				if (const Json *units = map.get(key))
					for (const Json &u : units->arr)
						if (map_unit_row(u) == CIV_UNIT_TEMPLATE_NONE && u.string("type").empty()) {
							// No type to fall back to: load_map_seeded leaves it out (REMAINING_GAPS SU3).
							++left_out;
							std::printf("      %s: %s is left out (no row)\n", e.path().filename().string().c_str(),
								u.string("template").c_str());
						} else if (map_unit_row(u) == CIV_UNIT_TEMPLATE_NONE) {
							++missing;
							std::printf("      %s: %s falls back to its class\n", e.path().filename().string().c_str(),
								u.string("template").c_str());
						}
		}
		std::snprintf(msg, sizeof msg, "every unit template of the %d ported maps has a roster row (%d fall back, %d left out)", maps, missing, left_out);
		check(maps >= 100 && missing == 0 && left_out == 0, msg);
	}

	std::printf("%d/%d checks passed (%u unit templates, %u hero auras)\n",
		g_checks - g_failed, g_checks, CIV_UNIT_TEMPLATE_COUNT, CIV_HERO_AURA_COUNT);
	return g_failed == 0 ? 0 : 1;
}
